<script setup lang="ts">
import QrcodeVue from'qrcode.vue';import type{ApiEnvelope,LinkRecord}from'~/types/api'
definePageMeta({layout:'dashboard',middleware:'auth'});const route=useRoute();const{update}=useLinks();const{request,requestBlob}=useApi();const error=ref('');const loading=ref(false);const showQr=ref(false);const{show}=useToast();const{data,pending,error:loadError}=await useAsyncData(`link-${route.params.id}`,()=>request<ApiEnvelope<LinkRecord>>(`links/${route.params.id}`));useSeoPage('Link details','Update a short link destination and settings.',`/dashboard/links/${route.params.id}`)
onMounted(()=>{if(route.query.created)show('Link created successfully.')})
async function submit(payload:Record<string,unknown>){loading.value=true;error.value='';try{const response=await update(Number(route.params.id),payload);if(data.value)data.value.data=response.data;show('Link updated.')}catch(e:any){error.value=Object.values(e?.data?.errors||{}).flat().join(' ')||e?.data?.message||'Unable to save changes.'}finally{loading.value=false}}
async function downloadQr(){try{const svg=await requestBlob(`links/${route.params.id}/qr`);const url=URL.createObjectURL(svg);const anchor=document.createElement('a');anchor.href=url;anchor.download=`${data.value?.data.short_code||'247url'}.svg`;anchor.click();URL.revokeObjectURL(url)}catch(e:any){show(e?.data?.message||'Unable to download QR code.','error')}}
</script>
<template><div class="dashboard-page"><NuxtLink to="/dashboard/links" class="text-xs text-text-muted hover:text-brand">← Back to links</NuxtLink><LoadingState v-if="pending" class="mt-5"/><div v-else-if="loadError" class="surface mt-5 p-6"><p class="text-sm text-danger">This link could not be loaded. It may not exist or may belong to another account.</p></div><template v-else-if="data"><div class="mt-4 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><h1 class="truncate text-2xl font-bold tracking-[-0.025em] text-brand">{{ data.data.short_url }}</h1><span :class="data.data.is_expired?'badge-warning':data.data.is_active?'badge-success':'badge-danger'">{{ data.data.is_expired?'Expired':data.data.is_active?'Active':'Disabled' }}</span></div><p class="mt-1 max-w-2xl truncate text-sm text-text-secondary">{{ data.data.destination_url }}</p></div><div class="flex gap-2"><CopyButton :text="data.data.short_url"/><button class="btn-secondary h-8 text-xs" @click="showQr=!showQr">QR code</button><NuxtLink :to="`/dashboard/links/${data.data.id}/analytics`" class="btn-primary h-8 text-xs">Analytics</NuxtLink></div></div><div class="mt-6 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div><p v-if="error" class="mb-4 rounded-lg border border-danger-border bg-danger-bg p-4 text-sm text-danger" role="alert">{{ error }}</p><LinkForm :key="data.data.updated_at" :link="data.data" :loading="loading" @submit="submit"/></div><aside class="grid gap-5"><section class="surface p-5"><h2 class="text-sm font-semibold">Link summary</h2><dl class="mt-4 divide-y divide-border"><div v-for="item in [['Clicks',data.data.clicks_count.toLocaleString()],['Created',new Date(data.data.created_at).toLocaleDateString()],['Expires',data.data.expires_at?new Date(data.data.expires_at).toLocaleString():'Never'],['Alias',data.data.custom_alias||'Generated']]" :key="item[0]" class="flex justify-between gap-4 py-3 text-xs"><dt class="text-text-muted">{{ item[0] }}</dt><dd class="text-right font-medium">{{ item[1] }}</dd></div></dl></section><section v-if="showQr" class="surface p-5 text-center"><h2 class="text-sm font-semibold">QR code</h2><div class="mt-4 inline-block rounded-md border border-border bg-white p-4"><QrcodeVue :value="data.data.short_url" :size="180" level="M" render-as="svg"/></div><button class="btn-secondary mt-4 w-full" type="button" @click="downloadQr">Download SVG</button></section></aside></div></template></div></template>
